Lemma lw32_range : forall c, 0 <= c < 2^32 -> 0 <= lw32 c < 2^64.
Proof. intros c Hc. unfold lw32. destruct (Z.ltb_spec c (2^31)); lia. Qed.

Lemma lw32_eq_iff : forall c k, 0 <= c < 2^32 -> 0 <= k < 2^31 -> (lw32 c = k <-> c = k).
Proof. intros c k Hc Hk. unfold lw32. destruct (Z.ltb_spec c (2^31)); lia. Qed.

Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Lemma rw_cells_ibW : forall lo hi X m m' A cs,
  rw_cells asegs m A cs -> munch (ibW lo hi X) m m' -> wmono asegs m m' ->
  (A + Z.of_nat (cells_size cs) <= lo \/ hi <= A) ->
  (forall x, x ∈ X -> A + Z.of_nat (cells_size cs) <= x \/ x + 32 <= A) ->
  rw_cells asegs m' A cs.
Proof.
  intros lo hi X m m' A cs H MU WM D1 D2. eapply rw_cells_transport; [exact H| exact MU| exact WM|]. apply disjoint_ibW; assumption.
Qed.

Lemma bytes_at_ibW : forall lo hi X m m' A bs,
  bytes_at asegs m A bs -> munch (ibW lo hi X) m m' ->
  (A + Z.of_nat (length bs) <= lo \/ hi <= A) ->
  (forall x, x ∈ X -> A + Z.of_nat (length bs) <= x \/ x + 32 <= A) ->
  bytes_at asegs m' A bs.
Proof.
  intros lo hi X m m' A bs H MU D1 D2. eapply bytes_at_transport; [exact H| exact MU|]. apply disjoint_ibW; assumption.
Qed.

Lemma AEMCells_ibW : forall lo hi X m m' em,
  AEMCells m em -> munch (ibW lo hi X) m m' -> wmono asegs m m' ->
  (forall e d, em !! e = Some d -> e + esize d <= lo \/ hi <= e + 48) ->
  (forall e d x, em !! e = Some d -> x ∈ X -> e + esize d <= x \/ x + 32 <= e + 48) ->
  AEMCells m' em.
Proof.
  intros lo hi X m m' em H MU WM D1 D2 e d L. eapply rw_cells_ibW; [exact (H e d L)| exact MU| exact WM| |].
  - rewrite ValCells_size. pose proof (D1 e d L). lia.
  - intros x IN. rewrite ValCells_size. pose proof (D2 e d x L IN). lia.
Qed.

Lemma ALSCells_ibW : forall lo hi X m m' ls,
  ALSCells m ls -> munch (ibW lo hi X) m m' -> wmono asegs m m' ->
  (forall a n, ls !! a = Some n -> a + 16 <= lo \/ hi <= a) ->
  (forall a n x, ls !! a = Some n -> x ∈ X -> a + 16 <= x \/ x + 32 <= a) ->
  ALSCells m' ls.
Proof.
  intros lo hi X m m' ls H MU WM D1 D2 a n L. destruct (H a n L) as [WF C]. split; [exact WF|].
  eapply rw_cells_ibW; [exact C| exact MU| exact WM| |].
  - rewrite LNodeCells_size. exact (D1 a n L).
  - intros x IN. rewrite LNodeCells_size. exact (D2 a n x L IN).
Qed.

