Lemma ANSR_store : forall m m' ns X a nd nd' pad k n,
  ANSR m ns X -> ns !! a = Some nd ->
  munch [(a + k, a + k + n)] m m' -> wmono asegs m m' -> 0 <= k -> k + n <= 32 ->
  node_wf nd' -> rw_cells asegs m' a (NodeCells nd' pad) ->
  ANSR m' (<[ a := nd' ]> ns) X.
Proof.
  intros m m' ns X a nd nd' pad k n NSR0 L MU WM K1 K2 WF C.
  eapply ANSR_store_gen; [exact NSR0| exact L| exact MU| exact WM| | exact WF| exact C].
  repeat apply Forall_cons; [right; cbn [fst snd]; lia| apply Forall_nil].
Qed.

End HCW.

