Ltac prove_inside_ibW :=
  first [ cbn [inside]; simpl_sizes; slia
        | simpl_sizes; apply inside_ibW_frame; lia
        | simpl_sizes;
          match goal with
          | H : ?x ∈ ?X |- inside (ibW _ _ ?X) _ _ => apply (inside_ibW_node _ _ _ x _ _ H); lia
          end ].

Ltac footprint_after_store segs m a bs ::=
  repeat match goal with
  | MU : munch ?Wq ?mq m |- _ =>
      first [ apply (munch_write Wq mq m a bs) in MU; [ | lia | simpl_sizes; slia | prove_inside_ibW ]
            | fail 100 "store outside the declared footprint:" a ]
  | WMo : wmono segs ?mq m |- _ => apply (wmono_write segs mq m (wa a) bs) in WMo
  | STq : stk segs m ?loq ?hiq |- _ =>
      first [ apply (stk_write segs m loq hiq a bs) in STq; [ | lia | simpl_sizes; slia ]
            | fail 100 "cannot transport stk hypothesis" STq ]
  end.

(* [comment removed for export] *)
Ltac nnode NSRH L CH :=
  let WF := fresh "WF" in let IN := fresh "IN" in let OUT := fresh "OUT" in let pad := fresh "pad" in let B := fresh "B" in
  destruct (ANSR_node _ _ _ _ _ NSRH L) as (WF & IN & OUT & [pad CH]);
  unfold node_wf in WF; unfold NodeCells, wz in CH;
  pose proof (rw_cells_bound _ _ _ _ CH) as B; cbn [cells_size csize Nat.add] in B.

(* [comment removed for export] *)
Ltac pre_store CH k n ML WL :=
  lazymatch type of CH with rw_cells _ ?mc ?x _ =>
    pose proof (munch_refl [(x + k, x + k + n)] mc) as ML; pose proof (wmono_refl asegs mc) as WL
  end.

(* [comment removed for export] *)
Ltac post_store NSRk Lx ML WL CH nd' k n :=
  let WFn := fresh "WFn" in
  assert (WFn : node_wf nd') by (unfold node_wf, RED, BLACK; cbn [n_par n_lft n_rgt n_col set_lft set_par set_rgt set_col]; lia);
  let N := fresh "NSR" in
  pose proof (ANSR_store _ _ _ _ _ _ nd' _ k n NSRk Lx ML WL ltac:(lia) ltac:(lia) WFn CH) as N;
  clear NSRk ML WL CH WFn; rename N into NSRk.

(* [comment removed for export] *)
Ltac mnode ns x nd L H :=
  destruct (ns !! x) as [nd|] eqn:L;
  [| exfalso; unfold get_parent, get_left, get_right, get_color, set_parent, set_left, set_right, set_color, load, store in H;
     rewrite L in H; cbn [mbind option_bind] in H; discriminate].

(* [comment removed for export] *)
Ltac mstep H L :=
  first [ apply (mb_store _ _ _ _ _ _ _ L) in H | apply (mb_load _ _ _ _ _ _ L) in H
        | apply (m_store_last _ _ _ _ _ _ L) in H | apply (m_load_last _ _ _ _ _ L) in H ];
  cbn [get_field set_field OFF_PARENT OFF_LEFT OFF_RIGHT OFF_COLOR Z.eqb Pos.eqb set_par set_lft set_rgt set_col] in H.

(* [comment removed for export] *)
Ltac mblock H r E :=
  lazymatch type of H with
  | mbind _ ?A = _ => destruct A as [r|] eqn:E; [cbn [mbind option_bind] in H| cbn [mbind option_bind] in H; discriminate]
  end.

(* [comment removed for export] *)
Ltac gen_store NSRk :=
  lazymatch type of NSRk with ANSR _ ?nsk _ =>
    let nsv := fresh "ns" in let E := fresh "Ens" in remember nsk as nsv eqn:E; clear E end.

(* [comment removed for export] *)
Ltac nload NSRk H x :=
  lazymatch type of NSRk with ANSR _ ?ns _ =>
    let nd := fresh "nd" in let L := fresh "L" in let CH := fresh "CH" in
    mnode ns x nd L H; mstep H L; nnode NSRk L CH; step; clear CH
  end.

(* [comment removed for export] *)
Ltac nstore NSRk H x k n mk :=
  lazymatch type of NSRk with ANSR _ ?ns _ =>
    let nd := fresh "nd" in let L := fresh "L" in let CH := fresh "CH" in let ML := fresh "ML" in let WL := fresh "WL" in
    mnode ns x nd L H; mstep H L; nnode NSRk L CH; pre_store CH k n ML WL; st1;
    let nd' := eval cbv beta in (mk nd) in
    post_store NSRk L ML WL CH nd' k n; gen_store NSRk; clear L
  end.

(* [comment removed for export] *)
Ltac name_val v x := let E := fresh "E" x in remember v as x eqn:E; clear E.

(* [comment removed for export] *)
Ltac nin NSRk H x :=
  lazymatch type of NSRk with ANSR _ ?ns _ =>
    let nd := fresh "nd" in let L := fresh "L" in
    let WF := fresh "WF" in let IN := fresh "IN" in let OUT := fresh "OUT" in let P := fresh "P" in
    mnode ns x nd L H;
    destruct (ANSR_node _ _ _ _ _ NSRk L) as (WF & IN & OUT & P);
    clear WF P L; clear nd
  end.

(* [comment removed for export] *)
Ltac nchk_rd NSRk x k RD :=
  lazymatch k with
  | 0 => pose proof (ANSR_rd0 _ _ _ x NSRk ltac:(assumption)) as RD
  | _ => pose proof (ANSR_rd _ _ _ x k NSRk ltac:(assumption) ltac:(lia)) as RD
  end.
Ltac nchk NSRk x k := let RD := fresh "RD" in nchk_rd NSRk x k RD; shchk_fast RD.
Ltac nchk_ld NSRk x k := let RD := fresh "RD" in nchk_rd NSRk x k RD; shchk_load RD.
Ltac nchk1 NSRk x k := let RD := fresh "RD" in nchk_rd NSRk x k RD; shchk_ld1 RD; shchk_br.
Ltac nchk1_ld NSRk x k := let RD := fresh "RD" in nchk_rd NSRk x k RD; shchk_ld1 RD.

(* [comment removed for export] *)
Ltac fld_ok_tac := unfold fld_ok, OFF_PARENT, OFF_LEFT, OFF_RIGHT, OFF_COLOR; reflexivity.
Ltac fld_ne_tac := first [ right; unfold OFF_PARENT, OFF_LEFT, OFF_RIGHT, OFF_COLOR; lia | left; lia ].
Ltac mswap_ls H :=
  unfold get_parent, get_left, get_right, get_color, set_parent, set_left, set_right, set_color in H;
  rewrite load_store_swap in H by first [ fld_ok_tac | fld_ne_tac ];
  fold_model H
with fold_model H :=
  change (load ?ns ?a OFF_PARENT) with (get_parent ns a) in H; change (load ?ns ?a OFF_LEFT) with (get_left ns a) in H;
  change (load ?ns ?a OFF_RIGHT) with (get_right ns a) in H; change (load ?ns ?a OFF_COLOR) with (get_color ns a) in H;
  change (store ?ns ?a OFF_PARENT ?v) with (set_parent ns a v) in H; change (store ?ns ?a OFF_LEFT ?v) with (set_left ns a v) in H;
  change (store ?ns ?a OFF_RIGHT ?v) with (set_right ns a v) in H; change (store ?ns ?a OFF_COLOR ?v) with (set_color ns a v) in H.
Ltac mswap_ss H :=
  unfold get_parent, get_left, get_right, get_color, set_parent, set_left, set_right, set_color in H;
  first [ rewrite store_store_swap in H by first [ fld_ok_tac | fld_ne_tac ]
        | rewrite store_store_comm in H by first [ fld_ok_tac | fld_ne_tac ] ];
  fold_model H.
Ltac mswap_ll H :=
  unfold get_parent, get_left, get_right, get_color, set_parent, set_left, set_right, set_color in H;
  rewrite load_load_swap in H;
  fold_model H.

